using System;using System.Collections;using System.Reflection;using UnityEngine;
public sealed class MildTackleTests:MonoBehaviour
{
 public static bool OverrideAxes=true;public static float FanAxis,ZhaoAxis;static bool started;
 const BindingFlags P=BindingFlags.Instance|BindingFlags.NonPublic;Component fan,zhao;Rigidbody2D fb,zb,ball;PlayerSkills fs,zs;Type pt;int failures,checks;
 public static void Boot(){if(started)return;started=true;var o=new GameObject("MildTackleTests");DontDestroyOnLoad(o);o.AddComponent<MildTackleTests>();}
 void Check(bool ok,string label){checks++;Debug.Log((ok?"MILD PASS ":"MILD FAIL ")+label);if(!ok)failures++;}
 object Field(PlayerSkills s,string n){return typeof(PlayerSkills).GetField(n,P).GetValue(s);}
 float Fx(){return zs==null?-10:((float[])Field(zs,"effects"))[3];}
 void Move(Component p,Rigidbody2D b,Vector2 pos){p.transform.position+=(Vector3)(pos-b.position);Physics2D.SyncTransforms();}
 float Joints(Component p){float max=0;foreach(HingeJoint2D j in p.GetComponentsInChildren<HingeJoint2D>())if(j.connectedBody!=null)max=Mathf.Max(max,Vector2.Distance(j.transform.TransformPoint(j.anchor),j.connectedBody.transform.TransformPoint(j.connectedAnchor)));return max;}
 bool LimbControl(){object[] m=(object[])Field(fs,"physicalMuscles");float[] f=(float[])Field(fs,"normalMuscleForces");FieldInfo field=(FieldInfo)Field(fs,"muscleForceField");for(int i=2;i<m.Length;i++)if(Mathf.Abs((float)field.GetValue(m[i])-f[i])>.01f)return false;return true;}
 IEnumerator Scene(bool skills){FanAxis=ZhaoAxis=0;PlayerSkills.Enabled=skills;typeof(GameAIMod).GetMethod("StartGame",BindingFlags.NonPublic|BindingFlags.Static).Invoke(null,new object[]{0});yield return new WaitForSeconds(.15f);pt=Type.GetType("PlayerController, Assembly-CSharp");fan=GameObject.Find("Fan").GetComponent(pt);zhao=GameObject.Find("Zhao").GetComponent(pt);fb=(Rigidbody2D)pt.GetField("rb").GetValue(fan);zb=(Rigidbody2D)pt.GetField("rb").GetValue(zhao);fs=fan.GetComponent<PlayerSkills>();zs=zhao.GetComponent<PlayerSkills>();ball=(FindObjectOfType(Type.GetType("Ball, Assembly-CSharp")) as Component).GetComponent<Rigidbody2D>();ball.gravityScale=0;ball.position=new Vector2(0,40);ball.velocity=Vector2.zero;}
 void Capture(string label){if(SystemInfo.graphicsDeviceType==UnityEngine.Rendering.GraphicsDeviceType.Null)return;Camera cam=Camera.main;RenderTexture previous=cam.targetTexture,active=RenderTexture.active;RenderTexture rt=new RenderTexture(1024,768,24);cam.targetTexture=rt;cam.Render();RenderTexture.active=rt;Texture2D png=new Texture2D(1024,768,TextureFormat.RGB24,false);png.ReadPixels(new Rect(0,0,1024,768),0,0);png.Apply();System.IO.File.WriteAllBytes(System.IO.Path.GetFullPath(System.IO.Path.Combine(Application.dataPath,"../../mild-tackle-"+label+".png")),png.EncodeToPNG());cam.targetTexture=previous;RenderTexture.active=active;rt.Release();Destroy(rt);Destroy(png);}
 IEnumerator Contact(bool skills,bool air,bool rear){yield return Scene(skills);float y=air?2.2f:fb.position.y;Move(fan,fb,new Vector2(-1.25f,y));Move(zhao,zb,new Vector2(1.25f,y));ball.position=new Vector2(rear?5:0,40);if(air){fan.GetComponent<Animator>().SetTrigger("Jump");zhao.GetComponent<Animator>().SetTrigger("Jump");}foreach(var b in fan.GetComponentsInChildren<Rigidbody2D>())b.velocity=new Vector2(air?3:0,air?2:0);foreach(var b in zhao.GetComponentsInChildren<Rigidbody2D>())b.velocity=new Vector2(air?-3:0,air?2:0);FanAxis=1;ZhaoAxis=-1;
  float first=-10,recovered=-10,maxTilt=0,maxDeviation=0,maxError=0,mass=zb.mass,gain=0,duration=0;bool control=true,captured=false;Component stick=fan.GetComponent(Type.GetType("StickManController, Assembly-CSharp"));
  for(int i=0;i<90;i++){yield return new WaitForFixedUpdate();maxError=Mathf.Max(maxError,Mathf.Max(Joints(fan),Joints(zhao)));if(Fx()>=0&&first<0){first=Time.time;gain=(float)Field(fs,"balanceGain");duration=(float)Field(fs,"staggerUntil")-Time.time;foreach(var relay in zhao.GetComponentsInChildren<PowerTackleContact>())relay.enabled=false;Check((bool)Field(fs,"weakenedBalance"),"real impact produces brief balance response air="+air+" rear="+rear);}
   if(first>=0){control&=LimbControl();if(recovered<0&&!(bool)Field(fs,"weakenedBalance"))recovered=Time.time-first;if(Time.time-first<.75f){maxTilt=Mathf.Max(maxTilt,Mathf.Abs(Mathf.DeltaAngle(0,fb.rotation)));maxDeviation=Mathf.Max(maxDeviation,Mathf.Abs(Mathf.DeltaAngle(fb.rotation,(float)stick.GetType().GetField("body").GetValue(stick))));}if(air&&!captured&&Time.time-first>.18f){captured=true;Capture(rear?"air-rear":"air-front");}}
  }
  Debug.Log("MILD RUN skills="+skills+" air="+air+" rear="+rear+" tilt="+maxTilt+" deviation="+maxDeviation+" joint="+maxError+" recovery="+recovered+" gain="+gain+" duration="+duration);
  if(!skills)Check(Fx()<0,"classic contact never triggers skill");else{Check(first>=0,"real contact activates with "+(rear?"rear":"front")+" ball air="+air);Check(control,"arms and legs retain their normal control throughout impact");Check(maxTilt<55&&maxDeviation<35,"impact remains a moderate stumble instead of folding");Check(recovered>=0&&recovered<=.75f,"full balance control returns within 0.75 seconds");Check(gain>=15&&duration<.34f,"shorter and milder balance weakening");Check(Mathf.Abs(zb.mass-mass)<.01f,"brace mass promptly restores");Check(maxError<.3f,"moderate impact keeps all joints connected");}
  Check(fan.GetComponentsInChildren<Joint2D>().Length==9&&zhao.GetComponentsInChildren<Joint2D>().Length==9,"all native joints retained");FanAxis=ZhaoAxis=0;
 }
 IEnumerator Guards(){yield return Scene(true);Move(fan,fb,new Vector2(-4,fb.position.y));Move(zhao,zb,new Vector2(1,zb.position.y));ball.position=new Vector2(5,40);for(int i=0;i<15;i++)yield return new WaitForFixedUpdate();Check(Fx()<0,"rear ball alone does not trigger without a body collision");typeof(PlayerSkills).GetMethod("Show",P).Invoke(zs,new object[]{3});Check(Fx()>=0,"skill animation is allowed with rear ball");PlayerSkills.ResetAll();Check(Fx()<0,"round reset clears tackle animation");}
 IEnumerator Start(){Application.targetFrameRate=60;Application.runInBackground=true;QualitySettings.vSyncCount=0;AudioListener.volume=0;yield return new WaitForSeconds(.2f);yield return Contact(false,false,false);yield return Contact(true,false,false);yield return Contact(true,true,false);yield return Contact(true,false,true);yield return Contact(true,true,true);yield return Guards();Check(PlayerSkills.TackleAirSpeed>PlayerSkills.TackleGroundSpeed,"aerial contact still has a modest advantage");Debug.Log("MILD TACKLE COMPLETE checks="+checks+" failures="+failures);Application.Quit();}
}
